package advprobe

import (
	"context"
	"testing"
	"time"

	"github.com/prometheus/prometheus/promql"
	"github.com/prometheus/prometheus/promql/promqltest"
	"github.com/prometheus/prometheus/util/stats"
)

func run(t *testing.T, load, q string, start, end, interval int64) *stats.QuerySamples {
	st := promqltest.LoadedStorage(t, load)
	t.Cleanup(func() { st.Close() })
	eng := promqltest.NewTestEngineWithOpts(t, promql.EngineOpts{
		Logger: nil, Reg: nil, MaxSamples: 1000000,
		Timeout: 10 * time.Second, EnableAtModifier: true, EnableNegativeOffset: true,
		EnablePerStepStats: true,
	})
	qry, err := eng.NewRangeQuery(context.Background(), st, &promql.QueryOpts{EnablePerStepStats: true},
		q, time.UnixMilli(start), time.UnixMilli(end), time.Duration(interval)*time.Millisecond)
	if err != nil {
		t.Fatal(err)
	}
	res := qry.Exec(context.Background())
	if res.Err != nil {
		t.Fatal(res.Err)
	}
	return qry.Stats().Samples
}

const load = `load 10s
  foo 0+1x100
`

func TestAtModifierMultiArg(t *testing.T) {
	for _, q := range []string{
		`predict_linear(foo[50s] @ 100, 3600)`,
		`rate(foo[50s] @ 100)`,
		`predict_linear(foo[50s], 3600)`,
		`quantile_over_time(scalar(foo), foo[50s] @ 100)`,
	} {
		s := run(t, load, q, 100000, 200000, 10000)
		t.Logf("%-45s TotalSamples=%d perStep=%v SamplesRead=%d readPerStep=%v",
			q, s.TotalSamples, s.TotalSamplesPerStep, s.SamplesRead, s.SamplesReadPerStep)
	}
}
EOF
go test ./... -run TestAtModifierMultiArg -v 2>&1 | tail -30
